CREATE TABLE report_definitions (definition_id UUID PRIMARY KEY,name TEXT NOT NULL,mode TEXT NOT NULL,audience TEXT NOT NULL,metric_version TEXT NOT NULL,template_version TEXT NOT NULL,code_version TEXT NOT NULL,required_source_types JSONB NOT NULL,benchmark TEXT NOT NULL,risk_free_rate NUMERIC NOT NULL,annualization_days INTEGER NOT NULL CHECK(annualization_days>0),base_currency CHAR(3) NOT NULL,sensitivity TEXT NOT NULL,required_template_fields JSONB NOT NULL);
CREATE TABLE report_runs (run_id UUID PRIMARY KEY,definition_id UUID NOT NULL REFERENCES report_definitions(definition_id),period_start DATE NOT NULL,period_end DATE NOT NULL,input_hash TEXT UNIQUE NOT NULL,content_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('CREATED','BUILDING','COMPLETED','INCOMPLETE','FAILED')),mode TEXT NOT NULL,template_version TEXT NOT NULL,code_version TEXT NOT NULL,benchmark TEXT NOT NULL,risk_free_rate NUMERIC NOT NULL,annualization_days INTEGER NOT NULL,fx_snapshot_id UUID,generated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE report_input_bindings (binding_id UUID PRIMARY KEY,run_id UUID NOT NULL REFERENCES report_runs(run_id),position INTEGER NOT NULL,source_type TEXT NOT NULL,source_id UUID NOT NULL,as_of TIMESTAMPTZ NOT NULL,content_hash TEXT NOT NULL,quality TEXT NOT NULL,source_mode TEXT NOT NULL,reference TEXT NOT NULL,facts JSONB NOT NULL,reconciled BOOLEAN NOT NULL,UNIQUE(run_id,position));
CREATE TABLE report_metrics (metric_id UUID PRIMARY KEY,run_id UUID NOT NULL REFERENCES report_runs(run_id),name TEXT NOT NULL,value NUMERIC NOT NULL,unit TEXT NOT NULL,definition TEXT NOT NULL,formula TEXT NOT NULL,source_snapshot_ids JSONB NOT NULL,source_references JSONB NOT NULL,drilldown_reference TEXT NOT NULL,UNIQUE(run_id,name));
CREATE TABLE report_sleeve_attributions (attribution_id UUID PRIMARY KEY,run_id UUID NOT NULL REFERENCES report_runs(run_id),component TEXT NOT NULL,dimension TEXT NOT NULL,value NUMERIC NOT NULL,source_run_id UUID,source_reference TEXT NOT NULL,instrument_id UUID);
CREATE TABLE report_strategy_summaries (summary_id UUID PRIMARY KEY,run_id UUID NOT NULL REFERENCES report_runs(run_id),kind TEXT NOT NULL,strategy_run_id UUID NOT NULL,select_count INTEGER NOT NULL,keep_count INTEGER NOT NULL,exit_count INTEGER NOT NULL,candidate_stability NUMERIC NOT NULL,turnover NUMERIC NOT NULL,daily_gate TEXT,rebalance_days JSONB NOT NULL,cash_state TEXT);
CREATE TABLE report_artifacts (artifact_id UUID PRIMARY KEY,run_id UUID NOT NULL REFERENCES report_runs(run_id),format TEXT NOT NULL,reference TEXT NOT NULL,content TEXT NOT NULL,content_hash TEXT NOT NULL,generated_at TIMESTAMPTZ NOT NULL,sensitivity TEXT NOT NULL,publishable BOOLEAN NOT NULL,UNIQUE(run_id,format));
CREATE TABLE report_quality_results (quality_id UUID PRIMARY KEY,run_id UUID NOT NULL REFERENCES report_runs(run_id),check_name TEXT NOT NULL,outcome TEXT NOT NULL,observed TEXT NOT NULL,expected TEXT NOT NULL,explanation TEXT NOT NULL,UNIQUE(run_id,check_name));
CREATE TABLE report_events (event_id UUID PRIMARY KEY,event_type TEXT NOT NULL,run_id UUID NOT NULL REFERENCES report_runs(run_id),occurred_at TIMESTAMPTZ NOT NULL,payload JSONB NOT NULL);
